"""myre.py -- a small backtracking regular-expression engine written from scratch.

Supported syntax (a subset of Python's ``re``):

* literals
* ``.``          any char except newline
* ``[abc]``      character classes, with ranges ``[a-z]`` and negation ``[^abc]``
* escapes        ``\\d \\D \\w \\W \\s \\S`` plus simple char escapes (``\\n`` ...)
* quantifiers    ``* + ?`` (greedy semantics, full backtracking)
* alternation    ``|``
* grouping       ``(...)``
* anchors        ``^`` (start of string) and ``$`` (end of string, or just
                 before a trailing newline -- identical to Python without
                 ``re.MULTILINE``)

Public API::

    match(pattern, s) -> bool

with search semantics: equivalent to ``bool(re.search(pattern, s))``.

This module deliberately does NOT import ``re``.
"""

from collections import deque

__all__ = ["match", "search", "compile_pattern", "RegexSyntaxError"]


class RegexSyntaxError(ValueError):
    """Raised for malformed or unsupported patterns."""


# --------------------------------------------------------------------------
# Character predicates (ASCII-oriented, mirroring Python's str semantics for
# the characters the engine is exercised with)
# --------------------------------------------------------------------------

def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_word(ch):
    return ch == "_" or ch.isalnum()


def _is_space(ch):
    return ch.isspace()


_KIND_PREDICATES = {
    "d": _is_digit,
    "w": _is_word,
    "s": _is_space,
}

_CHAR_ESCAPES = {
    "n": "\n",
    "t": "\t",
    "r": "\r",
    "f": "\f",
    "v": "\v",
    "a": "\a",
    "0": "\0",
}


# --------------------------------------------------------------------------
# AST
#
# Node shapes (tagged tuples):
#   ("char", c)                  literal character
#   ("dot",)                     .
#   ("class", items, negated)    items: ("c", ch) | ("r", lo, hi) | ("k", kind, kneg)
#   ("cat", [nodes])             concatenation (possibly empty -> empty match)
#   ("alt", [nodes])             alternation
#   ("rep", node, min, max)      quantifier; max is None for unbounded
#   ("bol",)                     ^
#   ("eol",)                     $
# --------------------------------------------------------------------------


class _Parser:
    def __init__(self, pattern):
        self.pat = pattern
        self.i = 0

    # -- helpers ------------------------------------------------------------
    def _peek(self):
        return self.pat[self.i] if self.i < len(self.pat) else None

    def _next(self):
        ch = self._peek()
        if ch is not None:
            self.i += 1
        return ch

    def _expect_close(self, what):
        if self._next() != ")":
            raise RegexSyntaxError("missing %s, unterminated subpattern" % what)

    # -- grammar ------------------------------------------------------------
    def parse(self):
        node = self._alternation()
        if self.i < len(self.pat):
            # only way to stop early is an unmatched ')'
            raise RegexSyntaxError("unbalanced parenthesis")
        return node

    def _alternation(self):
        branches = [self._concat()]
        while self._peek() == "|":
            self._next()
            branches.append(self._concat())
        if len(branches) == 1:
            return branches[0]
        return ("alt", branches)

    def _concat(self):
        parts = []
        while True:
            ch = self._peek()
            if ch is None or ch in "|)":
                break
            parts.append(self._repeat())
        return ("cat", parts)

    def _repeat(self):
        atom = self._atom()
        ch = self._peek()
        if ch in ("*", "+", "?"):
            if atom[0] in ("bol", "eol"):
                raise RegexSyntaxError("nothing to repeat")
            self._next()
            lo, hi = {"*": (0, None), "+": (1, None), "?": (0, 1)}[ch]
            return ("rep", atom, lo, hi)
        return atom

    def _atom(self):
        ch = self._peek()
        if ch == "(":
            self._next()
            inner = self._alternation()
            self._expect_close(")")
            # Groups are capture-transparent for boolean matching.
            return inner
        if ch == "[":
            return self._char_class()
        if ch == ".":
            self._next()
            return ("dot",)
        if ch == "^":
            self._next()
            return ("bol",)
        if ch == "$":
            self._next()
            return ("eol",)
        if ch == "\\":
            return self._escape_atom()
        if ch in ("*", "+", "?"):
            raise RegexSyntaxError("nothing to repeat")
        if ch == ")":
            raise RegexSyntaxError("unbalanced parenthesis")
        self._next()
        return ("char", ch)

    def _escape_atom(self):
        self._next()  # backslash
        ch = self._next()
        if ch is None:
            raise RegexSyntaxError("bad escape (end of pattern)")
        if ch in "dDwWsS":
            kind, neg = ch.lower(), ch.isupper()
            return ("class", [("k", kind, neg)], False)
        if ch == "b":
            raise RegexSyntaxError("\\b (word boundary) is not supported")
        return ("char", self._escape_char(ch))

    def _escape_char(self, ch):
        """Resolve an escape sequence to its literal character."""
        if ch in _CHAR_ESCAPES:
            return _CHAR_ESCAPES[ch]
        if ch.isalpha():
            raise RegexSyntaxError("bad escape \\%s" % ch)
        return ch  # \. \\ \[ \] \( \) \+ \* \? \| \^ \$ \- \/ ...

    # -- character classes ----------------------------------------------------
    def _char_class(self):
        self._next()  # '['
        negated = False
        if self._peek() == "^":
            negated = True
            self._next()
        items = []
        first = True
        while True:
            ch = self._peek()
            if ch is None:
                raise RegexSyntaxError("unterminated character set")
            if ch == "]" and not first:
                self._next()
                break
            first = False
            lo = self._class_atom()
            # Range?  Only "X-Y" where Y is not ']' (then '-' is a literal).
            if (
                self._peek() == "-"
                and self.i + 1 < len(self.pat)
                and self.pat[self.i + 1] != "]"
            ):
                self._next()  # '-'
                hi = self._class_atom()
                if lo[0] != "c" or hi[0] != "c":
                    raise RegexSyntaxError("bad character range")
                if ord(lo[1]) > ord(hi[1]):
                    raise RegexSyntaxError(
                        "bad character range %s-%s" % (lo[1], hi[1])
                    )
                items.append(("r", lo[1], hi[1]))
            else:
                items.append(lo)
        return ("class", items, negated)

    def _class_atom(self):
        """One element inside [...]: returns ("c", ch) or ("k", kind, kneg)."""
        ch = self._next()
        if ch is None:
            raise RegexSyntaxError("unterminated character set")
        if ch == "\\":
            esc = self._next()
            if esc is None:
                raise RegexSyntaxError("bad escape (end of pattern)")
            if esc in "dDwWsS":
                return ("k", esc.lower(), esc.isupper())
            if esc == "b":
                return ("c", "\x08")  # backspace, as in Python classes
            return ("c", self._escape_char(esc))
        return ("c", ch)


_COMPILE_CACHE = {}


def compile_pattern(pattern):
    """Parse *pattern* into an AST (cached)."""
    try:
        return _COMPILE_CACHE[pattern]
    except KeyError:
        pass
    except TypeError:  # unhashable (never happens for str, but be safe)
        return _Parser(pattern).parse()
    node = _Parser(pattern).parse()
    _COMPILE_CACHE[pattern] = node
    return node


# --------------------------------------------------------------------------
# Matcher: backtracking via enumeration of reachable end positions.
#
# _ends(node, s, i) yields every end index j such that the node matches
# s[i:j] along SOME parse.  Because we only need a boolean answer, exploring
# the full set of reachable positions is exactly equivalent to exhaustive
# backtracking (greedy order is irrelevant for existence).
# --------------------------------------------------------------------------


def _ends(node, s, i):
    tag = node[0]

    if tag == "char":
        if i < len(s) and s[i] == node[1]:
            yield i + 1

    elif tag == "dot":
        if i < len(s) and s[i] != "\n":
            yield i + 1

    elif tag == "class":
        if i < len(s) and _class_match(node[1], node[2], s[i]):
            yield i + 1

    elif tag == "bol":
        if i == 0:
            yield i

    elif tag == "eol":
        # Python (no MULTILINE): end of string, or just before a final '\n'.
        if i == len(s) or (i == len(s) - 1 and s[i] == "\n"):
            yield i

    elif tag == "cat":
        positions = {i}
        for child in node[1]:
            nxt = set()
            for p in positions:
                nxt.update(_ends(child, s, p))
            positions = nxt
            if not positions:
                return
        yield from positions

    elif tag == "alt":
        for branch in node[1]:
            yield from _ends(branch, s, i)

    elif tag == "rep":
        _, child, lo, hi = node
        # Breadth-first exploration of positions reachable with k repetitions;
        # zero-width child matches (k == p) are absorbed by the `depth` dict,
        # which is what makes e.g. (a*)* terminate.
        depth = {i: 0}
        order = [i]
        qi = 0
        while qi < len(order):
            p = order[qi]
            qi += 1
            if hi is not None and depth[p] == hi:
                continue
            for k in _ends(child, s, p):
                if k not in depth:
                    depth[k] = depth[p] + 1
                    order.append(k)
        for p in order:
            if depth[p] >= lo:
                yield p

    else:  # pragma: no cover
        raise AssertionError("unknown node %r" % (tag,))


def _class_match(items, negated, ch):
    hit = False
    for item in items:
        kind = item[0]
        if kind == "c":
            if ch == item[1]:
                hit = True
                break
        elif kind == "r":
            if item[1] <= ch <= item[2]:
                hit = True
                break
        else:  # ("k", kind, kneg): e.g. \d or its negation inside the class
            pred = _KIND_PREDICATES[item[1]]
            if pred(ch) != item[2]:
                hit = True
                break
    return hit != negated


# --------------------------------------------------------------------------
# Public API
# --------------------------------------------------------------------------


def match(pattern, s):
    """Return True iff *pattern* matches somewhere in *s*.

    Semantics identical to ``bool(re.search(pattern, s))`` for the supported
    subset of the syntax.
    """
    node = compile_pattern(pattern)
    # Try every start offset; anchors restrict naturally.
    for start in range(len(s) + 1):
        for _end in _ends(node, s, start):
            return True
    return False


